UPDATE post
   SET title = #{title,jdbcType=VARCHAR},
       content = #{content,jdbcType=CLOB}
 WHERE post_id = #{postId,jdbcType=NUMERIC}
   AND user_id = #{userId,jdbcType=NUMERIC}
   AND deleted_at IS NULL

UPDATE post
   SET deleted_at = SYSTIMESTAMP
 WHERE post_id = #{postId,jdbcType=NUMERIC}
   AND user_id = #{userId,jdbcType=NUMERIC}
   AND deleted_at IS NULL
